function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1e9 || v > 1e9)) return 'Each value is an integer between -10^9 and 10^9.';
  let low = Infinity, total = 0;
  for (const v of nums) low = Math.min(low, v);
  for (const v of nums) total += v - low;
  if (total > 2147483647) return 'The answer must fit in a 32-bit integer.';
  return null;
}

