function minMoves(nums) {
  // Simulate the real operation in batches: skip one largest element for (max - min) moves in a row,
  // which lifts the current minimum up to that largest value.
  const values = nums.slice();
  let count = 0;
  for (;;) {
    let top = 0, low = 0;
    for (let k = 1; k < values.length; k++) {
      if (values[k] > values[top]) top = k;
      if (values[k] < values[low]) low = k;
    }
    const gap = values[top] - values[low];
    if (gap === 0) return count;
    for (let k = 0; k < values.length; k++) if (k !== top) values[k] += gap;
    count += gap;
  }
}

