function generate(rand, size) {
  const LIMIT = 1e9, MAX_ANSWER = 2147483647;
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 7);
    const span = rand() < 0.3 ? 2 : 12;
    return [Array.from({ length: n }, () => int(-span, span))];
  }
  for (;;) {
    const n = 2000;
    const mode = Math.floor(rand() * 3);
    let nums;
    if (mode === 0) {
      // Many values in a narrow band anywhere in the allowed range.
      const base = int(-LIMIT, LIMIT - 1000000);
      nums = Array.from({ length: n }, () => base + int(0, 1000000));
    } else if (mode === 1) {
      // Almost everything sits at one value, with a few far-away outliers.
      const base = int(-LIMIT, 0);
      nums = Array.from({ length: n }, () => base);
      for (let k = 0; k < 2; k++) nums[int(0, n - 1)] = int(base, LIMIT);
    } else {
      // Small values with a negative minimum.
      nums = Array.from({ length: n }, () => int(-1000, 1000));
    }
    let low = Infinity, total = 0;
    for (const v of nums) low = Math.min(low, v);
    for (const v of nums) total += v - low;
    if (total <= MAX_ANSWER) return [nums];
  }
}
